#!/usr/bin/env python3
"""Verify an HTML generated by the label-audit skill."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
from pathlib import Path


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--html", type=Path, required=True)
    parser.add_argument("--decoder", type=Path)
    args = parser.parse_args()

    html = args.html.read_text()
    if 'class="reason-grid' not in html or 'type="checkbox"' not in html:
        raise RuntimeError("Audit viewer lacks multi-select rejection controls")
    if '<select class="reason-in' in html:
        raise RuntimeError("Audit viewer still uses the legacy single-reason dropdown")
    match = re.search(r"const DATA = (\{.*?\});\nconst SLUG", html, re.S)
    if not match:
        raise RuntimeError("Embedded DATA payload not found")
    payload = json.loads(match.group(1))
    rows = payload.get("rows") or []
    run_ids = [row.get("episodeId") for row in rows]
    segment_count = sum(len(row.get("segments") or []) for row in rows)
    if len(run_ids) != len(set(run_ids)):
        raise RuntimeError("Duplicate audit run IDs")
    if segment_count != payload.get("totalSegments"):
        raise RuntimeError("Embedded segment count mismatch")
    if any(not row.get("videoUrl") for row in rows):
        raise RuntimeError("One or more audit rows has no video URL")

    result = {
        "status": "pass",
        "html": str(args.html),
        "sha256": hashlib.sha256(args.html.read_bytes()).hexdigest(),
        "audit_runs": len(rows),
        "source_episodes": len({row.get("sourceEpisodeId") for row in rows}),
        "segments": segment_count,
    }
    if args.decoder:
        decoder = json.loads(args.decoder.read_text())
        if len(decoder.get("rows") or []) != len(rows):
            raise RuntimeError("Private decoder row count does not match audit HTML")
        result["decoder"] = str(args.decoder)
        result["decoder_sha256"] = hashlib.sha256(args.decoder.read_bytes()).hexdigest()
    print(json.dumps(result, indent=2))


if __name__ == "__main__":
    main()
